command:
set -eu
umask 022
nft_candidate=/etc/nftables.conf.antrieb-new
cat > "$nft_candidate" <<'ANTRIEB_NFT_EOF'
#!/usr/sbin/nft -f

flush ruleset

table inet host_firewall {
    chain input {
        type filter hook input priority filter; policy drop;

        iifname "lo" accept comment "Allow loopback"
        ct state established,related accept comment "Allow established and related traffic"
        ct state invalid drop comment "Drop invalid traffic"

        meta l4proto { icmp, ipv6-icmp } accept comment "Allow required ICMP and ICMPv6"
        udp sport 67 udp dport 68 accept comment "Allow DHCPv4 replies"
        udp sport 547 udp dport 546 accept comment "Allow DHCPv6 replies"

        tcp dport { 22, 8080 } accept comment "Allow SSH and application traffic"

        reject with icmpx type port-unreachable comment "Reject all other inbound traffic"
    }

    chain forward {
        type filter hook forward priority filter; policy drop;
    }

    chain output {
        type filter hook output priority filter; policy accept;
    }
}
ANTRIEB_NFT_EOF
nft --check --file "$nft_candidate"
install -o root -g root -m 0644 "$nft_candidate" /etc/nftables.conf
rm -f "$nft_candidate"
systemctl enable --now nftables
printf 'active='; systemctl is-active nftables
printf 'enabled='; systemctl is-enabled nftables
printf 'boot_id='; cat /proc/sys/kernel/random/boot_id
nft list ruleset

